@FunctionalInterface
interface Calc {
    int apply(int a, int b);
}

class Adder implements Calc {
    @Override
    public int apply(int a, int b) {
        return a + b;
    }
}

public class Main {
    public static void main(String[] args) {
        // 1. クラスを作る
        Calc c1 = new Adder();

        // 2. 匿名クラス
        Calc c2 = new Calc() {
            @Override
            public int apply(int a, int b) {
                return a + b;
            }
        };

        // 3. ラムダ式
        Calc c3 = (a, b) -> a + b;

        System.out.println(c1.apply(3, 4));
        System.out.println(c2.apply(3, 4));
        System.out.println(c3.apply(3, 4));
    }
}

@FunctionalInterface
interface Calc {
    int apply(int a, int b);
}

public class Main {
    // 処理そのものを引数で受け取れる
    static void show(String label, Calc calc, int a, int b) {
        System.out.println(label + ": " + calc.apply(a, b));
    }

    public static void main(String[] args) {
        show("足し算", (a, b) -> a + b, 6, 3);
        show("掛け算", (a, b) -> a * b, 6, 3);
        show("引き算", (a, b) -> a - b, 6, 3);
        show("大きい方", (a, b) -> a > b ? a : b, 6, 3);

        // {} を使う書き方（return が必要）
        Calc div = (a, b) -> {
            if (b == 0) {
                return 0;
            }
            return a / b;
        };
        System.out.println("割り算: " + div.apply(6, 0));
    }
}

