import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.Supplier;

public class Main {
    public static void main(String[] args) {
        Function<String, Integer> length = s -> s.length();
        Consumer<String> shout = s -> System.out.println(s + "!");
        Supplier<String> greeting = () -> "こんにちは";
        Predicate<String> isLong = s -> s.length() > 3;

        System.out.println("Function : " + length.apply("Java"));
        System.out.print("Consumer : ");
        shout.accept("Hello");
        System.out.println("Supplier : " + greeting.get());
        System.out.println("Predicate: " + isLong.test("Java"));

        // つなげる
        Function<Integer, String> label = n -> n + "文字";
        System.out.println("andThen  : " + length.andThen(label).apply("Silver"));
    }
}

import java.util.List;
import java.util.function.Consumer;
import java.util.function.Function;

public class Main {
    public static void main(String[] args) {
        List<String> words = List.of("apple", "fig", "banana");

        // ラムダで書く
        words.forEach(s -> System.out.println(s));

        System.out.println("--- メソッド参照 ---");
        words.forEach(System.out::println);

        System.out.println("--- 長さに変換 ---");
        Function<String, Integer> len = String::length;
        for (String w : words) {
            System.out.println(w + " " + len.apply(w));
        }

        Consumer<String> mark = s -> System.out.println("[" + s + "]");
        words.forEach(mark);
    }
}

