import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        List<String> words = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            words.add(sc.next());
        }

        List<String> byDict = new ArrayList<>(words);
        byDict.sort(Comparator.naturalOrder());
        System.out.println(byDict);

        List<String> byLength = new ArrayList<>(words);
        byLength.sort((s1, s2) -> {
            if (s1.length() != s2.length()) {
                return s1.length() - s2.length();
            }
            return s1.compareTo(s2);
        });
        System.out.println(byLength);

        List<String> reverse = new ArrayList<>(words);
        reverse.sort(Comparator.reverseOrder());
        System.out.println(reverse);
    }
}
